fn shell_game(n: i32, x: i8) -> i8 {
    // Reduce n modulo 6 since the position repeats every 6 moves
    let n_mod = (n % 6) as u8;
    let mut pos = x;

    for i in 1..=n_mod {
        if i % 2 == 1 {
            // Odd move: swap 0 and 1
            pos = match pos {
                0 => 1,
                1 => 0,
                2 => 2,
                _ => pos, // should not happen since positions are 0,1,2
            };
        } else {
            // Even move: swap 1 and 2
            pos = match pos {
                1 => 2,
                2 => 1,
                0 => 0,
                _ => pos,
            };
        }
    }

    pos
}